using System;
using Oathx.Widget;
using UnityEngine;

/// <summary>
/// Presents a local login notice without requesting server content.
/// </summary>
[Config("Assets/Data/Widgets/Notice/Notice.prefab", WidgetLayer.topmost, cacheWidget: false)]
public class UINotice : UIWidget<VMNotice>
{
    /// <summary>
    /// Persistent expiration key for automatic notice suppression.
    /// </summary>
    private const string reminderKey = "GameCLI.Notice.SuppressUntil";

    /// <summary>
    /// Bind page actions and reset the displayed notice.
    /// </summary>
    /// <returns>True when the page has a bound view model.</returns>
    public bool Initialize()
    {
        if (!vm)
            return false;

        vm.ExpandClick = (sender) => ToggleContent();
        vm.ArrowClick = (sender) => ToggleContent();
        vm.WeekClick = (sender) => ToggleReminder();
        vm.WeekAreaClick = (sender) => ToggleReminder();
        vm.Selected = IsReminderSuppressed();

        return SetContent(string.Empty, string.Empty);
    }

    /// <summary>
    /// Replace the displayed local notice; an empty body displays the empty state.
    /// </summary>
    /// <param name="title">Local notice title.</param>
    /// <param name="text">Local notice body; null or whitespace clears the notice.</param>
    /// <returns>True when the bound page has been updated.</returns>
    public bool SetContent(string title, string text)
    {
        if (!vm)
            return false;

        bool hasContent = !string.IsNullOrWhiteSpace(text);
        vm.NoticeTitleName = title ?? string.Empty;
        vm.Body = text ?? string.Empty;
        vm.Entry = hasContent;
        vm.Empty = !hasContent;
        vm.Expanded = hasContent;

        return true;
    }

    /// <summary>
    /// Toggle the visible body of the local notice.
    /// </summary>
    /// <returns>True when a notice was available to toggle.</returns>
    private bool ToggleContent()
    {
        if (!vm || !vm.Entry)
            return false;

        vm.Expanded = !vm.Expanded;
        return true;
    }

    /// <summary>
    /// Toggle and persist automatic notice suppression for seven days.
    /// </summary>
    /// <returns>True when the reminder preference was updated.</returns>
    private bool ToggleReminder()
    {
        if (!vm)
            return false;

        bool selected = !IsReminderSuppressed();
        if (selected)
            PlayerPrefs.SetString(reminderKey, DateTimeOffset.UtcNow.AddDays(7).ToUnixTimeSeconds().ToString(System.Globalization.CultureInfo.InvariantCulture));
        else
            PlayerPrefs.DeleteKey(reminderKey);

        PlayerPrefs.Save();
        vm.Selected = selected;
        return true;
    }

    /// <summary>
    /// Check whether automatic opening is suppressed; manual opening remains available.
    /// </summary>
    /// <returns>True while the saved expiration is in the future.</returns>
    public static bool IsReminderSuppressed()
    {
        return long.TryParse(PlayerPrefs.GetString(reminderKey, string.Empty), out long expires)
            && expires > DateTimeOffset.UtcNow.ToUnixTimeSeconds();
    }
}

using Oathx.Widget;

/// <summary>
/// Bindings for the local login notice page.
/// </summary>
public partial class VMNotice : VM
{
    /// <summary>
    /// Close button callback.
    /// </summary>
    [Binding]
    private ButtonClick closeClick;

    /// <summary>
    /// Notice header callback.
    /// </summary>
    [Binding]
    private ButtonClick expandClick;

    /// <summary>
    /// Notice arrow callback.
    /// </summary>
    [Binding]
    private ButtonClick arrowClick;

    /// <summary>
    /// Weekly reminder checkbox callback.
    /// </summary>
    [Binding]
    private ButtonClick weekClick;

    /// <summary>
    /// Weekly reminder label callback.
    /// </summary>
    [Binding]
    private ButtonClick weekAreaClick;

    /// <summary>
    /// Current local notice title.
    /// </summary>
    [Binding(typeof(SyncText))]
    private string noticeTitleName;

    /// <summary>
    /// Current local notice body.
    /// </summary>
    [Binding(typeof(SyncText))]
    private string body;

    /// <summary>
    /// Whether a local notice is available.
    /// </summary>
    [Binding(typeof(SyncVisible))]
    private bool entry;

    /// <summary>
    /// Whether the empty state is visible.
    /// </summary>
    [Binding(typeof(SyncVisible))]
    private bool empty;

    /// <summary>
    /// Whether the notice body is expanded.
    /// </summary>
    [Binding(typeof(SyncVisible))]
    private bool expanded;

    /// <summary>
    /// Whether automatic notices are suppressed for one week.
    /// </summary>
    [Binding(typeof(SyncVisible))]
    private bool selected;
}

using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;

/// <summary>
/// Fits the authored notice entry and scroll content to local body text.
/// </summary>
public class NoticeLayout : UIBehaviour
{
    /// <summary>
    /// Body text whose preferred height determines the entry size.
    /// </summary>
    [SerializeField]
    private Text body;

    /// <summary>
    /// Expandable body region.
    /// </summary>
    [SerializeField]
    private RectTransform expanded;

    /// <summary>
    /// Authored notice entry root.
    /// </summary>
    [SerializeField]
    private RectTransform entry;

    /// <summary>
    /// ScrollRect content root.
    /// </summary>
    [SerializeField]
    private RectTransform entries;

    /// <summary>
    /// Keep text, entry background and scroll bounds aligned after VM updates.
    /// </summary>
    private void LateUpdate()
    {
        if (body && expanded && entry && entries)
        {
            float height = Mathf.Max(46f, body.preferredHeight);
            body.rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, height);
            expanded.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, height + 40f);
            float entryHeight = expanded.gameObject.activeSelf ? height + 150f : 100f;
            entry.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, entryHeight);
            entries.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, entry.gameObject.activeSelf ? entryHeight : 0f);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Net;
using System.Text.RegularExpressions;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

/// <summary>
/// UGUI text with HTTP links whose hit areas follow the generated glyph geometry.
/// </summary>
public class NoticeText : Text, IPointerDownHandler, IPointerClickHandler
{
    /// <summary>
    /// Display color shared by valid links.
    /// </summary>
    [SerializeField]
    private Color linkColor = new Color(0.12f, 0.46f, 0.78f, 1f);

    /// <summary>
    /// Supported anchors with quoted or unquoted destinations.
    /// </summary>
    private static readonly Regex anchors = new Regex(
        @"<a\s+href\s*=\s*(?:""([^""]*)""|'([^']*)'|([^\s>]+))\s*>(.*?)</a\s*>",
        RegexOptions.IgnoreCase | RegexOptions.Singleline);

    /// <summary>
    /// Color tags are replaced inside links to keep link geometry identifiable.
    /// </summary>
    private static readonly Regex colors = new Regex(@"</?color(?:=[^>]+)?>", RegexOptions.IgnoreCase);

    /// <summary>
    /// Links belonging to the current text value.
    /// </summary>
    private readonly List<(string url, Color32 marker, List<Rect> bounds)> links = new List<(string, Color32, List<Rect>)>();

    /// <summary>
    /// Original input used to detect unchanged assignments.
    /// </summary>
    private string source;

    /// <summary>
    /// Pointer position at the beginning of a possible click.
    /// </summary>
    private Vector2 pressed;

    /// <summary>
    /// Parse anchor markup while keeping standard Text bindings compatible.
    /// </summary>
    public override string text
    {
        get { return base.text; }
        set
        {
            string input = value ?? string.Empty;
            if (source != input)
            {
                source = input;
                links.Clear();
                base.text = anchors.Replace(input, match => {
                    string destination = WebUtility.HtmlDecode(match.Groups[1].Success ? match.Groups[1].Value
                        : match.Groups[2].Success ? match.Groups[2].Value : match.Groups[3].Value);
                    string label = match.Groups[4].Value;
                    if (TryNormalizeUrl(destination, out string url))
                    {
                        int index = links.Count + 1;
                        var marker = new Color32(1, (byte)(index >> 8), (byte)index, 255);
                        links.Add((url, marker, new List<Rect>()));
                        return "<color=#" + ColorUtility.ToHtmlStringRGBA(marker) + ">" + colors.Replace(label, string.Empty) + "</color>";
                    }
                    return label;
                });
                supportRichText = true;
                SetVerticesDirty();
                SetLayoutDirty();
            }
        }
    }

    /// <summary>
    /// Build per-glyph hit boxes after Unity has performed wrapping and rich-text layout.
    /// </summary>
    /// <param name="mesh">Generated Text mesh.</param>
    protected override void OnPopulateMesh(VertexHelper mesh)
    {
        base.OnPopulateMesh(mesh);
        foreach (var link in links)
            link.bounds.Clear();

        var vertex = new UIVertex();
        for (int index = 0; index + 3 < mesh.currentVertCount; index += 4)
        {
            mesh.PopulateUIVertex(ref vertex, index);
            var link = links.Find(item => item.marker.Equals(vertex.color));
            if (link.bounds != null)
            {
                Vector2 min = vertex.position;
                Vector2 max = vertex.position;
                for (int corner = 0; corner < 4; corner++)
                {
                    mesh.PopulateUIVertex(ref vertex, index + corner);
                    min = Vector2.Min(min, vertex.position);
                    max = Vector2.Max(max, vertex.position);
                    vertex.color = linkColor;
                    mesh.SetUIVertex(vertex, index + corner);
                }
                if (max.x > min.x && max.y > min.y)
                    link.bounds.Add(Rect.MinMaxRect(min.x, min.y, max.x, max.y));
            }
        }
    }

    /// <summary>
    /// Remember the start of a click without taking ownership of ScrollRect dragging.
    /// </summary>
    /// <param name="data">Pointer press information.</param>
    public void OnPointerDown(PointerEventData data)
    {
        pressed = data.position;
    }

    /// <summary>
    /// Open a link only for a completed, stationary left-button click.
    /// </summary>
    /// <param name="data">Pointer click information.</param>
    public void OnPointerClick(PointerEventData data)
    {
        float threshold = EventSystem.current ? EventSystem.current.pixelDragThreshold : 10f;
        if (data.button == PointerEventData.InputButton.Left && !data.dragging && data.eligibleForClick
            && (data.position - pressed).sqrMagnitude <= threshold * threshold
            && TryGetLink(data.position, data.pressEventCamera, out string url))
        {
            Application.OpenURL(url);
        }
    }

    /// <summary>
    /// Resolve a visible hyperlink at a screen point, respecting parent masks.
    /// </summary>
    /// <param name="point">Screen-space pointer position.</param>
    /// <param name="camera">Event camera, or null for an overlay canvas.</param>
    /// <param name="url">Normalized destination when a link was hit.</param>
    /// <returns>True when the point is inside a visible link glyph.</returns>
    public bool TryGetLink(Vector2 point, Camera camera, out string url)
    {
        url = string.Empty;
        if (!IsActive() || !Raycast(point, camera)
            || !RectTransformUtility.ScreenPointToLocalPointInRectangle(rectTransform, point, camera, out Vector2 local))
            return false;

        foreach (var link in links)
        {
            if (link.bounds.Exists(rect => rect.Contains(local)))
            {
                url = link.url;
                return true;
            }
        }
        return false;
    }

    /// <summary>
    /// Accept absolute HTTP and HTTPS destinations without executable URI schemes.
    /// </summary>
    /// <param name="value">Destination supplied by the announcement.</param>
    /// <param name="url">Normalized browser destination.</param>
    /// <returns>True for a supported absolute web address.</returns>
    public static bool TryNormalizeUrl(string value, out string url)
    {
        url = string.Empty;
        if (!Uri.TryCreate(value, UriKind.Absolute, out Uri uri)
            || (uri.Scheme != Uri.UriSchemeHttp && uri.Scheme != Uri.UriSchemeHttps)
            || string.IsNullOrEmpty(uri.Host))
            return false;

        url = uri.AbsoluteUri;
        return true;
    }
}

using Oathx.Core;
using Oathx.Widget;

/// <summary>
/// Manages local announcement content and the notice page lifecycle.
/// </summary>
public class NoticeSystem : RuntimeSystem
{
    /// <summary>
    /// Local sample title used until live announcement content is connected.
    /// </summary>
    private const string defaultTitle = "欢迎体验 · 公告功能测试";

    /// <summary>
    /// Local sample covering rich text, web links and scrolling without server data.
    /// </summary>
    private const string defaultContent =
        "<b>欢迎来到游戏！</b>\n\n" +
        "这是一份本地测试公告，用于检查文字排版、超链接、滚动和展开收起，不代表正式运营通知。\n\n" +
        "<size=40><b>一、文字显示</b></size>\n" +
        "普通文字应清晰显示，长句应根据公告区域宽度自动换行，不超出面板边界。\n" +
        "<b>这是加粗文字</b>，<i>这是斜体文字</i>。\n" +
        "<color=#D46A26>这是需要重点关注的提示文字。</color>\n\n" +
        "<size=40><b>二、超链接测试</b></size>\n" +
        "点击蓝色文字，会使用系统浏览器打开对应网页：\n" +
        "<a href=\"https://example.com\">打开示例网站（测试链接）</a>\n" +
        "<a href=\"https://example.org\">打开另一个示例网站，检查多个链接是否分别响应</a>\n\n" +
        "以下为长链接，用于检查自动换行后的点击区域：\n" +
        "<a href=\"https://example.com/\">这是一段用于测试跨行点击的超链接文字，请分别点击第一行和换行后的文字，确认它们都能打开同一个示例网站，并检查链接前后的普通文字不会触发跳转。</a>\n\n" +
        "<size=40><b>三、滚动与交互</b></size>\n" +
        "1. 在正文区域上下拖动，检查长公告是否能够顺畅滚动。\n" +
        "2. 从蓝色链接文字处开始拖动，应该只滚动内容，不打开网页。\n" +
        "3. 点击公告标题或箭头，检查正文的收起和展开。\n" +
        "4. 勾选“一周内不再提示”，关闭后重新打开，检查勾选状态是否保留。\n" +
        "5. 点击右上角关闭按钮，应返回登录页面。\n\n" +
        "<size=40><b>四、底部检查</b></size>\n" +
        "看到这里，说明已经滚动到公告底部。请检查最后一行没有被裁掉。\n" +
        "<a href=\"https://example.net\">底部测试链接</a>\n\n" +
        "<color=#888888>—— 本地公告测试文本结束 ——</color>";

    /// <summary>
    /// Open the notice page and initialize its local content and close action.
    /// </summary>
    /// <returns>True after requesting page opening while active.</returns>
    public override bool OnActive()
    {
        if (!IsActive())
            return false;

        UISystem.GetSingleton().OpenWidget<UINotice>((widget) => {
            if (widget && widget.Initialize())
            {
                widget.vm.CloseClick = (sender) => CloseNotice();
                widget.SetContent(defaultTitle, defaultContent);
            }
        });

        return true;
    }

    /// <summary>
    /// Ask MasterSystem to unload the notice after an explicit close request.
    /// </summary>
    /// <returns>True when the unload request was queued.</returns>
    private bool CloseNotice()
    {
        if (!IsActive())
            return false;

        return XPluginUtility.PostEvent(new SystemDetive() {
            type = typeof(NoticeSystem)
        });
    }

    /// <summary>
    /// Release subscriptions and close the notice page when deactivated.
    /// </summary>
    public override void OnDetive()
    {
        UnsubscribeAll();

        System.Type[] widgets = new System.Type[] {
            typeof(UINotice)
        };

        UISystem.GetSingleton().CloseWidget(widgets, immediate: true);
    }
}
